def compute_dense_reward(self, action, obs):
    """Positive-control: potential-based progress + mild collision/success."""
    import numpy as np
    cur_d = float(np.linalg.norm(obs[0:2] - obs[4:6]))
    pre = getattr(self, "pre_obs", None)
    if pre is None:
        prev_d = cur_d
    else:
        prev_d = float(np.linalg.norm(pre[0:2] - pre[4:6]))
    r_progress = 1.0 * (prev_d - cur_d)
    comfort = 0.5
    if obs[7] < comfort:
        r_clearance = -5.0 * (comfort - float(obs[7]))
    else:
        r_clearance = 0.0
    total = r_progress + r_clearance
    collision = 0.0
    success = 0.0
    if float(obs[7]) < 0.0:
        collision = -100.0
        total += collision
        return total, {"progress": r_progress, "clearance": r_clearance, "collision": collision}
    if cur_d <= float(obs[6]):
        success = 500.0
        total += success
        return total, {"progress": r_progress, "clearance": r_clearance, "success": success}
    return total, {"progress": r_progress, "clearance": r_clearance}

def compute_dense_reward(self, action: np.ndarray, obs: np.ndarray) -> Tuple[float, Dict[str, float]]:
    prev_pos = self.pre_obs[0:2]
    goal = obs[4:6]
    prev_dist = np.linalg.norm(prev_pos - goal)
    delta = prev_dist - float(np.linalg.norm(obs[0:2] - obs[4:6]))
    progress = delta * 1.1
    if delta < 0.0:
        progress -= 0.9 * abs(delta)
    min_d = min(obs[7], obs[13], obs[14])
    if min_d < 0.0:
        clearance = -50.0
    elif min_d < 0.3:
        clearance = -5.5 * (0.3 - min_d)
    else:
        clearance = 0.0
    if float(np.linalg.norm(obs[2:4])) < 0.08 and float(np.linalg.norm(obs[0:2] - obs[4:6])) > 0.7:
        freeze = -0.45
    else:
        freeze = 0.0
    act = -0.015 * np.sum(action**2)
    reward = progress + clearance + freeze + act
    info = {"progress": progress, "clearance": clearance, "freeze": freeze, "act": act}
    return reward, info
